#!/usr/bin/env bash
# Chaos fork reproduction (docs/chaos-report.md section 1).
#
# Requires: anvil running against a Sepolia fork (e.g.
#   anvil --fork-url https://ethereum-sepolia-rpc.publicnode.com
# ) and cast. The calldata below is the ABI encoding of
#   executeGuarded([borrowMore(hf)], [getUserAccountData(guard) word5 GTE 1.4e18])
# for the deployed Sepolia guard (0x4Bd0501fb1c0dEecaCD3efd50340Cd82Bb8E7F0f) and
# position contract (0x2BeaFD2Ed0D8e3831752b3243E7C5b2CA67Fdb0B), generated with the
# eth-abi reference encoder and verified by round-trip decode.
set -euo pipefail

RPC="${RPC:-http://127.0.0.1:8545}"
EXECUTOR=0x5Fe224c6A6AFb471517848d5A0C6aa1905cDD582
GUARD=0x4Bd0501fb1c0dEecaCD3efd50340Cd82Bb8E7F0f

SAFE=""
UNSAFE=""

echo "== 1. safe rebalance (ends at HF 1.5) — expect success =="
cast call --rpc-url "$RPC" --from "$EXECUTOR" "$GUARD" "$SAFE"

echo "== 2. unsafe rebalance (ends at HF 1.12) — expect NOYEET/1:INV:0:1120000000000000000:1400000000000000000 =="
cast call --rpc-url "$RPC" --from "$EXECUTOR" "$GUARD" "$UNSAFE" 2>&1 || true

echo "== 3. non-executor — expect NOYEET/1:NOT_EXECUTOR =="
cast call --rpc-url "$RPC" --from 0x0000000000000000000000000000000000000BAD "$GUARD" "$SAFE" 2>&1 || true

echo "== 4. broadcast the safe composite — expect status 1 =="
cast send --rpc-url "$RPC" --unlocked --from "$EXECUTOR" --gas-limit 500000 "$GUARD" "$SAFE"

echo "== 5. broadcast the unsafe composite — expect status 0 + INV revert, state unchanged =="
cast send --rpc-url "$RPC" --unlocked --from "$EXECUTOR" --gas-limit 500000 "$GUARD" "$UNSAFE" 2>&1 || true
